<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #1a1a2e;
    color: #eee;
    font-family: 'Segoe UI', Arial, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    gap: 16px;
  }
  h1 {
    font-size: 2rem;
    color: #a8edea;
    letter-spacing: 4px;
    text-transform: uppercase;
  }
  #score-container {
    font-size: 1.3rem;
    color: #fed6e3;
    letter-spacing: 2px;
  }
  #score { font-weight: bold; color: #fff; }
  #snake {
    display: block;
    border: 3px solid #a8edea;
    border-radius: 4px;
    background: #16213e;
    box-shadow: 0 0 30px #a8edea44;
  }
  #controls {
    display: flex;
    gap: 12px;
  }
  button {
    padding: 10px 28px;
    border: 2px solid #a8edea;
    background: transparent;
    color: #a8edea;
    font-size: 1rem;
    border-radius: 6px;
    cursor: pointer;
    letter-spacing: 1px;
    transition: background 0.2s, color 0.2s;
  }
  button:hover {
    background: #a8edea;
    color: #1a1a2e;
  }
  #status {
    font-size: 1rem;
    color: #fed6e3;
    min-height: 1.4em;
    letter-spacing: 1px;
  }
</style>
</head>
<body>
<h1>🐍 Snake</h1>
<div id="score-container">Score: <span id="score">0</span></div>
<canvas id="snake" width="420" height="420"></canvas>
<div id="controls">
  <button id="start">Start</button>
  <button id="pause">Pause</button>
  <button id="reset">Reset</button>
</div>
<div id="status">Press Start to play!</div>

<script>
(function() {
  const COLS = 21, ROWS = 21;
  const CELL = 20; // 21*20 = 420px
  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const statusEl = document.getElementById('status');

  // Game state
  let snakeArr = [];
  let foodPos = [0, 0];
  let dir = 'right';
  let nextDir = 'right';
  let _score = 0;
  let _alive = false;
  let loopInterval = null;
  let running = false;

  const OPPOSITE = { up: 'down', down: 'up', left: 'right', right: 'left' };

  function initSnake() {
    // Start in middle, heading right, length 3
    const midY = Math.floor(ROWS / 2);
    const midX = Math.floor(COLS / 2);
    snakeArr = [
      [midX, midY],
      [midX - 1, midY],
      [midX - 2, midY]
    ];
    dir = 'right';
    nextDir = 'right';
  }

  function randomFreeCell() {
    const occupied = new Set(snakeArr.map(([x,y]) => x + ',' + y));
    const free = [];
    for (let x = 0; x < COLS; x++)
      for (let y = 0; y < ROWS; y++)
        if (!occupied.has(x + ',' + y)) free.push([x, y]);
    if (free.length === 0) return null;
    return free[Math.floor(Math.random() * free.length)];
  }

  function placeFood() {
    const cell = randomFreeCell();
    if (cell) foodPos = cell;
  }

  function reset() {
    initSnake();
    _score = 0;
    _alive = true;
    scoreEl.textContent = '0';
    statusEl.textContent = 'Use arrow keys to steer.';
    placeFood();
    draw();
  }

  function tick() {
    if (!_alive) return;
    dir = nextDir;

    const head = snakeArr[0];
    let nx = head[0], ny = head[1];
    if (dir === 'up') ny--;
    else if (dir === 'down') ny++;
    else if (dir === 'left') nx--;
    else if (dir === 'right') nx++;

    // Wall collision
    if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) {
      _alive = false;
      statusEl.textContent = 'Game Over! Hit a wall.';
      draw();
      stopLoop();
      return;
    }

    // Self collision (exclude tail tip because it will move)
    for (let i = 0; i < snakeArr.length - 1; i++) {
      if (snakeArr[i][0] === nx && snakeArr[i][1] === ny) {
        _alive = false;
        statusEl.textContent = 'Game Over! Hit yourself.';
        draw();
        stopLoop();
        return;
      }
    }

    const ate = (nx === foodPos[0] && ny === foodPos[1]);
    snakeArr.unshift([nx, ny]);
    if (ate) {
      _score++;
      scoreEl.textContent = _score;
      placeFood();
    } else {
      snakeArr.pop();
    }
    draw();
  }

  function setDir(d) {
    if (!_alive) return;
    if (d === OPPOSITE[dir]) return; // ignore 180°
    nextDir = d;
  }

  function setFood(x, y) {
    foodPos = [x, y];
    draw();
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Background grid
    ctx.fillStyle = '#16213e';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = '#1e2d50';
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= COLS; x++) {
      ctx.beginPath();
      ctx.moveTo(x * CELL, 0);
      ctx.lineTo(x * CELL, ROWS * CELL);
      ctx.stroke();
    }
    for (let y = 0; y <= ROWS; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * CELL);
      ctx.lineTo(COLS * CELL, y * CELL);
      ctx.stroke();
    }

    // Food
    const fx = foodPos[0] * CELL, fy = foodPos[1] * CELL;
    ctx.fillStyle = '#ff6b6b';
    ctx.shadowColor = '#ff6b6b';
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.arc(fx + CELL/2, fy + CELL/2, CELL/2 - 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // Snake
    const len = snakeArr.length;
    for (let i = len - 1; i >= 0; i--) {
      const [sx, sy] = snakeArr[i];
      const t = i / Math.max(len - 1, 1);
      // Head is bright green, tail darker
      const r = Math.round(80 + (1 - t) * 80);
      const g = Math.round(200 + (1 - t) * 55);
      const b = Math.round(80 + (1 - t) * 20);
      ctx.fillStyle = i === 0 ? '#a8edea' : `rgb(${r},${g},${b})`;
      if (i === 0) {
        ctx.shadowColor = '#a8edea';
        ctx.shadowBlur = 12;
      } else {
        ctx.shadowBlur = 0;
      }
      const margin = i === 0 ? 1 : 2;
      ctx.beginPath();
      ctx.roundRect(sx * CELL + margin, sy * CELL + margin, CELL - margin*2, CELL - margin*2, 4);
      ctx.fill();
    }
    ctx.shadowBlur = 0;

    // Game over overlay
    if (!_alive && len > 0) {
      ctx.fillStyle = 'rgba(0,0,0,0.55)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#ff6b6b';
      ctx.font = 'bold 2rem Segoe UI, Arial, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2 - 10);
      ctx.fillStyle = '#eee';
      ctx.font = '1.1rem Segoe UI, Arial, sans-serif';
      ctx.fillText('Score: ' + _score, canvas.width / 2, canvas.height / 2 + 24);
      ctx.textAlign = 'left';
    }
  }

  function startLoop() {
    if (loopInterval) return;
    loopInterval = setInterval(tick, 120);
    running = true;
  }

  function stopLoop() {
    clearInterval(loopInterval);
    loopInterval = null;
    running = false;
  }

  // Buttons
  document.getElementById('start').addEventListener('click', () => {
    if (!_alive) reset();
    startLoop();
    statusEl.textContent = 'Running…';
  });
  document.getElementById('pause').addEventListener('click', () => {
    if (running) {
      stopLoop();
      statusEl.textContent = 'Paused.';
    } else if (_alive) {
      startLoop();
      statusEl.textContent = 'Running…';
    }
  });
  document.getElementById('reset').addEventListener('click', () => {
    stopLoop();
    reset();
    statusEl.textContent = 'Press Start to play!';
  });

  // Keyboard
  document.addEventListener('keydown', (e) => {
    switch (e.key) {
      case 'ArrowUp':    e.preventDefault(); setDir('up');    break;
      case 'ArrowDown':  e.preventDefault(); setDir('down');  break;
      case 'ArrowLeft':  e.preventDefault(); setDir('left');  break;
      case 'ArrowRight': e.preventDefault(); setDir('right'); break;
    }
  });

  // Public API
  window.game = {
    w: COLS,
    h: ROWS,
    reset() { stopLoop(); reset(); },
    tick() { tick(); },
    setDir(d) { setDir(d); },
    setFood(x, y) { setFood(x, y); },
    snake() { return snakeArr.map(c => [c[0], c[1]]); },
    food() { return [foodPos[0], foodPos[1]]; },
    alive() { return _alive; },
    score() { return _score; }
  };

  // Init
  reset();
})();
</script>
</body>
</html>
